//! The tool table: every tool Stage's AI control surface
//! offers, the same for the in-app Generate panel, the MCP server and the
//! CLI. Stage registers a live implementation per name
//! (`app/src/product/studio_api_host.rs`); a tool without one answers
//! "not available yet: <backed_by>".
//!
//! Conventions the descriptions teach:
//! - Times are seconds on the cut's timeline, as numbers.
//! - Media is named by exact revision: `{"asset_id": "…", "revision": "…"}`
//!   as `search_library` returns it.
//! - Blocks are named by their node id (`timeline` lists them).
//! - Every mutating tool is one undoable step in the CUT page; its result
//!   carries the cut's new `revision` and a unified `diff` of the source.

use crate::spec::{Family, Layout, ToolSpec};
use makepad_gen_tools as gen;
use makepad_score_tools as score;
use makepad_kernel_tools as kernel;

// Schema fragments, as macros so `concat!` can splice them.
macro_rules! asset_ref {
    ($what:literal) => {
        concat!(r#"{"type": "object", "description": ""#, $what, r#"", "properties": {"asset_id": {"type": "string", "minLength": 1, "description": "the asset id"}, "revision": {"type": "string", "minLength": 1, "description": "the exact revision"}}, "required": ["asset_id", "revision"]}"#)
    };
}
/// The state of a web grab (the `web_grab_*` tools).
macro_rules! grab_out {
    () => {
        r#"{"type": "object", "additionalProperties": true, "properties": {"job": {"type": "integer", "description": "the grab job id"}, "state": {"type": "string", "enum": ["opening", "waiting", "recording", "finishing", "done", "failed", "cancelled"], "description": "where it stands"}, "note": {"type": "string", "description": "why it waits or failed"}, "recorded_s": {"type": "number", "description": "seconds of the source recorded so far"}, "target_s": {"type": "number", "description": "seconds it will hold"}, "progress": {"type": "number", "description": "0..1"}, "asset": {"type": "object", "description": "the finished clip: {asset_id, revision}, as search_library names media"}}}"#
    };
}
macro_rules! no_args {
    () => {
        r#"{"type": "object", "properties": {}}"#
    };
}
macro_rules! base_revision {
    () => {
        r#""base_revision": {"type": "integer", "description": "the cut revision you read; when given and the cut has changed since (the person edited it), the call is refused so you can re-read instead of overwriting"}"#
    };
}
/// The result of every mutating tool.
macro_rules! mutation_out {
    () => {
        r#"{"type": "object", "additionalProperties": true, "properties": {"revision": {"type": "integer", "description": "the cut's revision after the change"}, "changed": {"type": "array", "items": {"type": "string", "description": "node id"}, "description": "nodes added or changed"}, "diff": {"type": "string", "description": "unified diff of the cut source"}, "note": {"type": "string", "description": "what the page said about the change"}}, "required": ["revision"]}"#
    };
}
macro_rules! open_out {
    () => {
        r#"{"type": "object", "additionalProperties": true, "properties": {}}"#
    };
}
macro_rules! target {
    () => {
        r#""target": {"type": "string", "description": "`cut` (default) for the open cut, or a motion document's name"}"#
    };
}
macro_rules! image_out {
    () => {
        r#"{"type": "object", "additionalProperties": true, "properties": {"width": {"type": "integer", "description": "picture width"}, "height": {"type": "integer", "description": "picture height"}, "times": {"type": "array", "items": {"type": "number", "description": "seconds"}, "description": "the times shown"}, "exposure": {"type": "object", "additionalProperties": true, "properties": {}, "description": "one frame: clipped and near_black (shares 0..1 of pixels at 99%+ in a channel, and below 2.5% luma), mean_luma and range (2nd–98th percentile luma); several frames: most_clipped and most_near_black (share, frame, t) and mean_luma"}, "coverage": {"type": "array", "items": {"type": "object", "additionalProperties": true, "properties": {}, "description": "a Scene3D: graphic, scene (layer path), width and height of its layer, times; nodes: name, path, line, share (0..1 of the scene's picture at each time, what is in front counted), box [x, y, w, h] in document units where largest (null: never seen) and box_at; background: the share no node covers"}, "description": "per 3D scene shown, what each node that draws surfaces covers"}}}"#
    };
}

/// A storyboard item's fields (add and update take the same ones).
macro_rules! board_fields {
    () => {
        r##""row": {"type": "string", "description": "the row id (storyboard_read lists them: story, visuals, voice, music, refs, notes)"}, "title": {"type": "string", "description": "scene, treatment or page: its title"}, "intent": {"type": "string", "description": "scene: the ONE idea it carries"}, "mood": {"type": "string", "description": "scene: the feeling"}, "look": {"type": "string", "description": "scene or chapter: what is on screen and how it moves"}, "skill": {"type": "string", "description": "chapter: the skill or topic it is named after, e.g. EASING"}, "bars": {"type": "string", "description": "scene as a shot: the bars it covers, e.g. 9–12"}, "camera": {"type": "string", "description": "scene as a shot: the camera"}, "why": {"type": "string", "description": "scene as a shot: why this shot"}, "lyric": {"type": "string", "description": "scene as a shot: the lyric over it"}, "idea": {"type": "string", "description": "treatment: the idea in a few lines"}, "pun": {"type": "string", "description": "lyric: the joke the line makes"}, "set": {"type": "string", "description": "lyric: the set that makes it"}, "voice": {"type": "string", "description": "lyric: its type voice (an id of the board's voices; empty clears)"}, "device": {"type": "string", "description": "lyric: what the type does"}, "name": {"type": "string", "description": "device: the running device's name, e.g. P(doom)"}, "value": {"type": "string", "description": "device: its value at this occurrence"}, "palette": {"type": "array", "items": {"type": "string", "description": "#rrggbb"}, "description": "treatment: its palette"}, "chosen": {"type": "boolean", "description": "treatment: the one the person picked (choosing one un-chooses the others on its row)"}, "body": {"type": "string", "description": "page: its text (markdown-ish): palette and colour arc per section, type, the character model sheet, props, off-limits"}, "refs": {"type": "array", "items": {"type": "string", "description": "item id"}, "description": "page: the references it points at"}, "hero": {"type": "string", "description": "chapter: its one hero element"}, "out": {"type": "string", "description": "chapter: the transition out, motivated by its hero (the ball grows into the next background)"}, "band": {"type": "string", "description": "where in the frame it goes: a band of the board's layout (shorts: tag, headline, content, meta, floor); empty clears"}, "kit": {"type": "string", "description": "scene: a style kit, e.g. @swiss"}, "music": {"type": "string", "description": "scene: where it sits in the music, e.g. bars 1-4, on the drop"}, "media": {"type": "string", "description": "scene: media it needs generated or found"}, "stack": {"type": "string", "description": "scene: its layer stack back to front, e.g. graphic · detail · type · 3D with the named kits"}, "text": {"type": "string", "description": "note: the words (on the voice row: the voiceover line); lyric: the sung line"}, "media_type": {"type": "string", "enum": ["image", "video", "audio", "motion", "cut", "frame", "url", "swatch", "font", "file"], "description": "ref: what it is"}, "asset": {"type": ["object", "null"], "properties": {"asset_id": {"type": "string", "description": "the asset id"}, "revision": {"type": "string", "description": "the exact revision"}}, "required": ["asset_id", "revision"], "description": "ref: the library revision it shows (search_library gives them); null removes it"}, "at": {"type": "number", "minimum": 0, "description": "ref of a frame: seconds into its video"}, "url": {"type": "string", "description": "ref: a web address"}, "colors": {"type": "array", "items": {"type": "string", "description": "#rrggbb"}, "description": "ref of a swatch: its colours"}, "font": {"type": "string", "description": "ref: a font name"}, "label": {"type": "string", "description": "ref: its caption"}, "note": {"type": "string", "description": "ref: why it is here, what to take from it; device: how it shows here"}, "role": {"type": "string", "enum": ["reference", "use", "generate"], "description": "ref: reference = only to look at for style or mood; use = goes into the video as it is; generate = source for a generative segment (image-to-video, img2img, video-to-video) with prompt/flow/seed"}, "from": {"type": "string", "description": "scene: the picture/video reference to generate this scene's footage from"}, "prompt": {"type": "string", "description": "generate: what to make of the picture"}, "negative": {"type": "string", "description": "generate: what to avoid"}, "flow": {"type": "string", "description": "generate: a FLOW preset key (default bundled:image-to-video for pictures); generate_status lists what the LAN runs"}, "seed": {"type": "integer", "minimum": 0, "description": "generate: the seed"}, "color": {"type": "string", "description": "a note's colour, or a chapter's ground colour, #rrggbb (empty: the row's)"}"##
    };
}
/// A generation job, as every gen.* tool that follows one answers.
macro_rules! gen_job_out {
    () => {
        r#"{"type": "object", "additionalProperties": true, "properties": {"id": {"type": "string", "description": "the job id"}, "phase": {"type": "string", "description": "running, choosing, done, failed, cancelled"}, "assets": {"type": "array", "items": {"type": "object", "additionalProperties": true, "properties": {}, "description": "{asset_id, revision, kind, stage, alias?, title?}"}, "description": "what it published"}}, "required": ["id", "phase"]}"#
    };
}

/// The result of every storyboard change.
macro_rules! board_out {
    () => {
        r#"{"type": "object", "additionalProperties": true, "properties": {"revision": {"type": "string", "description": "the board's content revision after the change"}, "changed": {"type": "array", "items": {"type": "string", "description": "item id"}, "description": "items added or changed"}, "changes": {"type": "string", "description": "what changed, in words"}, "stale": {"type": "array", "items": {"type": "string", "description": "item id"}, "description": "items whose part of the cut is now out of date"}}, "required": ["revision"]}"#
    };
}

macro_rules! transition_obj {
    ($what:literal) => {
        concat!(r#"{"type": "object", "description": ""#, $what, r#"", "properties": {"seconds": {"type": "number", "minimum": 0, "description": "how long the change takes"}, "effect": {"type": "string", "description": "a transition preset id from list_effects kind `transition` (empty: a dissolve)"}, "p1": {"type": "number", "description": "the preset's first dial"}, "p2": {"type": "number", "description": "the preset's second dial"}, "p3": {"type": "number", "description": "the preset's third dial"}}, "required": ["seconds"]}"#)
    };
}

const fn tool(name: &'static str, family: Family, mutates: bool, images: bool, backed_by: &'static str, description: &'static str, input: &'static str, output: &'static str) -> ToolSpec {
    ToolSpec { name, family, description, input, output, mutates, images, backed_by, request: false, layout: None }
}

/// A tool that makes something: the chat shows it as a settings card first.
const fn request(name: &'static str, family: Family, mutates: bool, images: bool, backed_by: &'static str, layout: Layout, description: &'static str, input: &'static str, output: &'static str) -> ToolSpec {
    ToolSpec { name, family, description, input, output, mutates, images, backed_by, request: true, layout: Some(layout) }
}

use Family::*;

macro_rules! project_path {
    () => { r#""project": {"type": "string", "description": "project path (tree alias); omit for the open project"}, "# };
}

macro_rules! render_file {
    () => { r#""file": {"type": "string", "description": "logical cut file path inside project; omit for the open cut"}, "# };
}

